import { createFileRoute } from '@tanstack/react-router';
import { Settings2 } from 'lucide-react';
import { OrganizationSettingsPage } from '@/components/settings/organization/organization-settings-page';

export const Route = createFileRoute('/$owner/settings/organization')({
  component: OrganizationSettingsRoute,
});

function OrganizationSettingsRoute() {
  const { owner } = Route.useParams();

  return (
    <div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <Settings2 className="h-7 w-7" />
          <h1 className="text-3xl font-semibold leading-tight">Organization settings</h1>
        </div>
        <p className="text-sm text-muted-foreground">
          Rename this workspace, set agent write defaults, change visibility, or
          delete it.
        </p>
      </div>
      <OrganizationSettingsPage owner={owner} />
    </div>
  );
}

import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { Filter, Plus } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import {
  ConnectorMark,
  resolveConnectorDisplay,
} from "@/components/connectors/connector-display";
import { FacetChips } from "@/components/connectors/facet-chips";
import { getAuthMethods } from "@/components/entity-tabs/connections-tab/auth-methods";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  type ConnectionFacets,
  type ConnectorDefinitionItem,
  type ConnectionConnectorGroup,
  useAuthProfiles,
  useConnectionConnectorGroups,
  useInstallableConnectorCatalog,
} from "@/lib/api/connections";
import { useWorkspaceRoot } from "@/lib/api/entities";
import {
  type InferenceCatalogItem,
  type InferenceProviderItem,
  useInferenceProviderCatalog,
  useInferenceProviders,
} from "@/lib/api/inference-providers";
import { type SandboxItem, useSandboxes } from "@/lib/api/sandboxes";
import {
  CONNECTOR_FILTER_LABELS,
  type ConnectorFilter,
  connectorMatchesFilter,
  deriveConnectorFacets,
} from "@/lib/connectors/facets";
import { buildInferenceConnectorRows } from "@/lib/connectors/inference-rows";
import {
  buildSandboxConnectorRows,
  sandboxProviderFaviconDomain,
} from "@/lib/connectors/sandbox-rows";
import { OWNER_SECTIONS } from "@/lib/owner-sections";

export const Route = createFileRoute("/$owner/connectors/")({
  validateSearch: (search: Record<string, unknown>): { entity_id?: string } =>
    typeof search.entity_id === "string" ? { entity_id: search.entity_id } : {},
  loader: ({ context: { queryClient }, params }) => {
    // Await nothing — every prefetch is fire-and-forget. The component
    // mounts on the first frame, and OwnerWorkspaceGate passes its loading
    // state through so the page chrome remains visible above the list skeleton.
    void queryClient.prefetchQuery(
      useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner })
    );
  },
  component: ConnectionsLandingPage,
});

const FILTERS: ReadonlyArray<ConnectorFilter> = [
  "all",
  "data",
  "chat",
  "actions",
  "inference",
  "runtime",
  "oauth",
  "api_key",
  "app_install",
  "device",
  "needs_setup",
];

function ConnectionsLandingPage() {
  const { owner } = Route.useParams();
  const { entity_id: entityIdParam } = Route.useSearch();

  return (
    <OwnerWorkspaceGate owner={owner}>
      {(props) => (
        <ConnectionsLandingContent
          ownerSlug={props.ownerSlug}
          organizationId={props.organizationId}
          isWorkspaceLoading={props.isWorkspaceLoading}
          entityId={entityIdParam ? Number(entityIdParam) : undefined}
        />
      )}
    </OwnerWorkspaceGate>
  );
}

function ConnectionsLandingContent({
  ownerSlug,
  organizationId,
  isWorkspaceLoading,
  entityId,
}: {
  ownerSlug: string;
  organizationId: string | null;
  isWorkspaceLoading: boolean;
  entityId?: number;
}) {
  const { data: groups = [], isLoading: isGroupsLoading } =
    useConnectionConnectorGroups(organizationId ?? "", { entityId });
  // The full installable catalog (installed org defs merged with bundled
  // catalog entries). The list renders only INSTALLED connectors (see the
  // items filter below); the catalog is still fetched here so uninstalled
  // entries can resolve display icons for any that slip through, and so the
  // "Add connector" page shares a warm cache. Browsing/adding uninstalled
  // connectors happens on /connectors/create, not here.
  const { data: installedDefs = [], isLoading: isDefsLoading } =
    useInstallableConnectorCatalog(organizationId ?? "");
  const { data: authProfiles = [] } = useAuthProfiles(organizationId, {});
  const { data: inferenceProviders = [], isLoading: isProvidersLoading } =
    useInferenceProviders({ enabled: entityId == null });
  // Provider rows join the inference catalog by `kind` for their icon — the
  // catalog is the only place a provider's logo lives.
  const { data: inferenceCatalog = [] } = useInferenceProviderCatalog({
    enabled: entityId == null,
  });
  // Sandboxes are org-wide remote runtimes; same scope rule as providers.
  const { data: sandboxesPayload, isLoading: isSandboxesLoading } =
    useSandboxes({ enabled: entityId == null });
  const isContentLoading =
    isWorkspaceLoading ||
    isGroupsLoading ||
    isDefsLoading ||
    (entityId == null && (isProvidersLoading || isSandboxesLoading));
  // Providers / sandboxes are org-wide, not entity-linked. Keep this explicit
  // guard because a disabled query can still return cached data.
  const scopedInferenceProviders =
    entityId == null ? inferenceProviders : [];
  const scopedSandboxes =
    entityId == null ? (sandboxesPayload?.sandboxes ?? []) : [];

  // Page padding comes from the connectors layout. The list column sits flush
  // left (max-w-3xl caps the line length), matching the rest of the section.
  return (
    <div className="flex w-full max-w-3xl flex-1 flex-col gap-6">
      {entityId != null && (
        <div className="flex items-center gap-2 rounded-lg bg-card px-3 py-2 text-sm">
          <Filter className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-muted-foreground">
            Showing connectors linked to one entity
          </span>
          <Button asChild variant="ghost" size="sm" className="ml-auto h-6">
            <Link
              to="/$owner/connectors"
              params={{ owner: ownerSlug }}
              search={{}}
            >
              Show all
            </Link>
          </Button>
        </div>
      )}

      <ConnectionsLandingInner
        ownerSlug={ownerSlug}
        isContentLoading={isContentLoading}
        entityScoped={entityId != null}
        groups={groups}
        installedDefs={installedDefs}
        authProfiles={authProfiles}
        inferenceProviders={scopedInferenceProviders}
        inferenceCatalog={inferenceCatalog}
        sandboxes={scopedSandboxes}
      />
    </div>
  );
}

function ConnectionsLandingInner({
  ownerSlug,
  isContentLoading,
  entityScoped,
  groups,
  installedDefs,
  authProfiles,
  inferenceProviders,
  inferenceCatalog,
  sandboxes,
}: {
  ownerSlug: string;
  isContentLoading: boolean;
  entityScoped: boolean;
  groups: ConnectionConnectorGroup[];
  installedDefs: ConnectorDefinitionItem[];
  authProfiles: NonNullable<ReturnType<typeof useAuthProfiles>["data"]>;
  inferenceProviders: InferenceProviderItem[];
  inferenceCatalog: InferenceCatalogItem[];
  sandboxes: SandboxItem[];
}) {
  const navigate = useNavigate();
  const [filter, setFilter] = useState<ConnectorFilter>("all");

  const items = useMemo(() => {
    const groupMap = new Map(groups.map((g) => [g.connector_key, g] as const));
    const defMap = new Map<string, ConnectorDefinitionItem>();
    for (const def of installedDefs) defMap.set(def.key, def);
    for (const group of groups) {
      if (!defMap.has(group.connector_key)) {
        defMap.set(group.connector_key, {
          key: group.connector_key,
          name: group.connector_name ?? group.connector_key,
          description: null,
          version: "",
          auth_schema: null,
          feeds_schema: null,
          actions_schema: null,
          options_schema: null,
          status: "active",
          login_enabled: false,
          favicon_domain: group.favicon_domain,
          facets: group.facets,
        } as ConnectorDefinitionItem & { facets?: ConnectionFacets });
      }
    }

    // Model-provider rows, synthesized from `inference_providers`. They carry
    // no group, no auth profiles, and no setup state — a provider without a
    // working key surfaces that as its own `status`, not as "needs setup".
    const providerItems = buildInferenceConnectorRows(inferenceProviders).map(
      (row) => ({
        connector: row.connector,
        group: undefined,
        profileCounts: {
          env: 0,
          oauth_app: 0,
          oauth_account: 0,
          browser_session: 0,
        },
        facets: row.facets,
        needsSetup: false,
        provider: row.provider as InferenceProviderItem | undefined,
        sandbox: undefined as SandboxItem | undefined,
      })
    );

    // Remote-sandbox rows, synthesized from `/sandboxes`. A missing vault
    // credential is `status: error` (and needsSetup), not a separate surface.
    const sandboxItems = buildSandboxConnectorRows(sandboxes).map((row) => ({
      connector: row.connector,
      group: undefined,
      profileCounts: {
        env: 0,
        oauth_app: 0,
        oauth_account: 0,
        browser_session: 0,
      },
      facets: row.facets,
      needsSetup: !row.sandbox.connected,
      provider: undefined as InferenceProviderItem | undefined,
      sandbox: row.sandbox,
    }));

    const connectorItems = Array.from(defMap.values())
      // The list is the org's INSTALLED connectors only — the browsable catalog
      // of not-yet-added connectors lives on the "Add connector" page
      // (/connectors/create). A connector belongs here once it's installed or
      // has at least one connection (a group). Uninstalled catalog entries are
      // reachable via "Add connector", so nothing is stranded.
      .filter(
        (connector) =>
          connector.installed ||
          (groupMap.get(connector.key)?.connection_count ?? 0) > 0
      )
      .map((connector) => {
        const group = groupMap.get(connector.key);
        const methods = getAuthMethods(connector.auth_schema);
        const profileCounts = authProfiles.reduce(
          (acc, profile) => {
            if (profile.connector_key !== connector.key) return acc;
            acc[profile.profile_kind] += 1;
            return acc;
          },
          { env: 0, oauth_app: 0, oauth_account: 0, browser_session: 0 }
        );
        const facets = deriveConnectorFacets(connector, group);
        const needsSetup = connectorNeedsSetup(
          connector,
          group,
          methods,
          profileCounts
        );
        return {
          connector,
          group,
          profileCounts,
          facets,
          needsSetup,
          provider: undefined as InferenceProviderItem | undefined,
          sandbox: undefined as SandboxItem | undefined,
        };
      });

    return [...connectorItems, ...providerItems, ...sandboxItems]
      .filter((item) => connectorMatchesFilter(item, filter))
      .sort((a, b) => {
        // Every item here is installed or has connections, so "needs setup"
        // (installed-but-unconfigured) floats to the top as the actionable set.
        if (a.needsSetup && !b.needsSetup) return -1;
        if (!a.needsSetup && b.needsSetup) return 1;
        return a.connector.name.localeCompare(b.connector.name);
      });
  }, [
    authProfiles,
    filter,
    groups,
    installedDefs,
    inferenceProviders,
    sandboxes,
  ]);

  // Nothing added yet → the list page has nothing to show, so land the user
  // straight in the catalog. `replace` keeps Back from bouncing through the
  // empty list. Entity-scoped views keep their own (filtered) empty rendering.
  const emptyCatalog =
    !isContentLoading && items.length === 0 && filter === "all" && !entityScoped;
  useEffect(() => {
    if (emptyCatalog) {
      void navigate({
        to: "/$owner/connectors/create",
        params: { owner: ownerSlug },
        replace: true,
      });
    }
  }, [emptyCatalog, navigate, ownerSlug]);

  const addConnector = (
    <Button asChild variant="outline" size="sm" className="h-8 shrink-0 text-xs">
      <Link to="/$owner/connectors/create" params={{ owner: ownerSlug }}>
        <Plus className="mr-1.5 h-3.5 w-3.5" />
        Add connector
      </Link>
    </Button>
  );

  // Reserved-footprint skeleton — the same bordered row list the loaded page
  // uses, so nothing reflows when the groups land.
  if (isContentLoading) {
    return (
      <div className="space-y-4">
        <div className="flex justify-end">{addConnector}</div>
        <div
          className="overflow-hidden rounded-lg border"
          role="status"
          aria-label="Loading connectors"
        >
          {Array.from({ length: 6 }).map((_, i) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
              key={i}
              className={`flex items-center gap-3 px-3 py-2.5 ${
                i === 5 ? "" : "border-b"
              }`}
            >
              <Skeleton className="h-7 w-7 shrink-0 rounded-md" />
              <div className="min-w-0 flex-1 space-y-1.5">
                <Skeleton className="h-4 w-40" />
                <Skeleton className="h-3 w-24" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (emptyCatalog) {
    return null;
  }

  return (
    <div className="space-y-4">
      {/* Lede row matches InfraTabScaffold: short description left, Add right.
          Filters sit on their own row below so the many chips can wrap without
          colliding with the button. */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-muted-foreground">
          Tools your agents use for data, conversations, actions, inference, and
          remote runtimes. Sandbox providers are kinds in Add connector (Runtime
          filter); device-bound connectors show under On device.
        </p>
        {addConnector}
      </div>
      <div className="flex flex-wrap items-center gap-1.5">
        {FILTERS.map((key) => (
          <Button
            key={key}
            type="button"
            variant={filter === key ? "secondary" : "ghost"}
            size="sm"
            className="h-7 px-2 text-xs"
            onClick={() => setFilter(key)}
          >
            {CONNECTOR_FILTER_LABELS[key]}
          </Button>
        ))}
      </div>

      {items.length === 0 ? (
        <TabEmptyState
          icon={OWNER_SECTIONS.connectors.icon}
          title="No connectors match this filter"
          description="Try another capability or auth filter."
          secondaryActionLabel="Show all"
          secondaryOnAction={() => setFilter("all")}
        />
      ) : (
        <div className="overflow-hidden rounded-lg border">
          {items.map(
            (
              {
                connector,
                group,
                facets,
                profileCounts,
                needsSetup,
                provider,
                sandbox,
              },
              idx
            ) => {
              const defsMap = new Map(
                installedDefs.map((d) => [d.key, d] as const)
              );
              // Provider rows have no connector definition; their icon joins
              // the inference catalog by `kind` (the provider's catalog
              // identity). Custom kinds miss the catalog and degrade to the
              // letter-mark. Sandbox rows use the sandbox name only.
              const display = resolveConnectorDisplay(connector.key, defsMap, {
                name: connector.name,
                iconUrl: provider
                  ? inferenceCatalog.find((c) => c.slug === provider.kind)
                      ?.iconUrl
                  : undefined,
                faviconDomain:
                  connector.favicon_domain ??
                  group?.favicon_domain ??
                  // Sandboxes have no definition and no catalog to join, so
                  // their logo comes from the provider kind's domain.
                  (sandbox
                    ? sandboxProviderFaviconDomain(sandbox.providerKind)
                    : undefined),
              });
              const accountCount =
                profileCounts.oauth_account + profileCounts.browser_session;
              const connectionCount = group?.connection_count ?? 0;
              // Provider / sandbox rows have no connections/accounts to count —
              // their meta is the credential state that actually matters.
              const meta = provider
                ? [provider.isDefault ? "Default" : null, provider.status]
                    .filter(Boolean)
                    .join(" · ")
                : sandbox
                  ? [
                      sandbox.providerKind,
                      sandbox.connected ? "Connected" : "No credential",
                    ].join(" · ")
                  : [
                      `${connectionCount} ${
                        connectionCount === 1 ? "connection" : "connections"
                      }`,
                      accountCount > 0
                        ? `${accountCount} ${accountCount === 1 ? "account" : "accounts"}`
                        : null,
                      profileCounts.oauth_app > 0
                        ? `${profileCounts.oauth_app} OAuth app${
                            profileCounts.oauth_app === 1 ? "" : "s"
                          }`
                        : null,
                    ]
                      .filter(Boolean)
                      .join(" · ");
              const rowClassName = `flex items-center gap-3 px-3 py-2.5 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground ${
                idx === items.length - 1 ? "" : "border-b"
              }`;
              // Prefixed keys (inference / sandbox) route to the same detail
              // path; the detail page branches on the prefix.
              const rowBody = (
                <>
                  <ConnectorMark
                    icon={display.icon}
                    iconUrl={display.iconUrl}
                    name={display.name}
                    faviconDomain={display.faviconDomain}
                    className="h-7 w-7 shrink-0 rounded-md text-[10px]"
                  />
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="truncate text-sm font-medium">
                        {display.name}
                      </span>
                      <FacetChips facets={facets} />
                    </div>
                    <p className="truncate text-xs text-muted-foreground">
                      {meta}
                    </p>
                  </div>
                  {needsSetup ? (
                    <Badge variant="secondary" className="shrink-0 text-[10px]">
                      Needs setup
                    </Badge>
                  ) : null}
                </>
              );

              return (
                <Link
                  key={connector.key}
                  to="/$owner/connectors/$connectorKey"
                  params={{ owner: ownerSlug, connectorKey: connector.key }}
                  className={rowClassName}
                >
                  {rowBody}
                </Link>
              );
            }
          )}
        </div>
      )}
    </div>
  );
}

function connectorNeedsSetup(
  connector: ConnectorDefinitionItem,
  group: ConnectionConnectorGroup | undefined,
  methods: ReturnType<typeof getAuthMethods>,
  profileCounts: Record<
    "env" | "oauth_app" | "oauth_account" | "browser_session",
    number
  >
): boolean {
  // "Needs setup" means an INSTALLED connector is missing a required binding
  // (credentials / OAuth app / app install / device) — NOT merely "not added".
  // Uninstalled catalog entries no longer render in this list, so being
  // uninstalled is not a setup state here.
  if (
    methods.some((m) => m.type === "oauth") &&
    profileCounts.oauth_app === 0
  ) {
    return true;
  }
  if (methods.some((m) => m.type === "env_keys") && profileCounts.env === 0) {
    return true;
  }
  if (methods.some((m) => m.type === "app_installation") && !group) {
    return true;
  }
  // Device-bound connector (declares a required_capability) with no connection
  // yet: its runtime binding is unsatisfied. `!group` mirrors the app_install
  // branch above — resolveDeviceBinding guarantees no connection exists for
  // these without a valid device, so a group implies the binding is done.
  if (connector.required_capability && !group) {
    return true;
  }
  return false;
}

/**
 * Routed Organization Settings page.
 *
 * Replaces the modal "Manage Organization" dialog that used to live inside the
 * org-switcher dropdown — see DESIGN_GUIDELINES §1 (no destructive actions in
 * Dialogs) and §8 (no Sheet-shaped editors in Dialogs). The delete affordance
 * is an inline two-step `[Confirm] [Cancel]` swap inside a
 * `border-destructive/30` danger zone, matching the exemplar in
 * `app/$owner/devices/$deviceId.tsx`.
 *
 * Agent write defaults use the same matrix as each agent's Permissions tab
 * (org floor = principal null).
 */

import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { Globe2, Lock, ShieldCheck, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { AgentPermissionsMatrix } from "@/components/agents/agent-permissions-matrix";
import { TabLoadingState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Spinner } from "@/components/ui/spinner";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type Organization as ApiOrganization,
	type OrganizationVisibility,
	updateOrganizationVisibility,
	useOrganizations,
} from "@/lib/api";
import { isServerError } from "@/lib/api/core";
import { organization } from "@/lib/auth";
import {
	buildOwnerHref,
	getSubdomainOwner,
	getSubdomainZone,
} from "@/lib/subdomain";
import { stripOwnerPrefix } from "@/lib/subdomain-history";

function slugifyOrganizationName(value: string) {
	return value
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "");
}

function getRenamedOrganizationPath(
	currentPath: string,
	currentSlug: string,
	nextSlug: string,
) {
	const segments = currentPath.split("/");
	if (segments[1] === currentSlug) {
		segments[1] = nextSlug;
		return segments.join("/") || "/";
	}
	return `/${nextSlug}`;
}

interface OrganizationSettingsPageProps {
	owner: string;
}

export function OrganizationSettingsPage({
	owner,
}: OrganizationSettingsPageProps) {
	const navigate = useNavigate();
	const queryClient = useQueryClient();
	const { data: allOrgs, error: orgsError } = useOrganizations();
	const { activeOrg, urlOrgSlug } = useOrgContext();

	const targetOrg: ApiOrganization | null =
		(allOrgs ?? []).find((o) => o.slug === owner && o.is_member) ?? null;

	const [name, setName] = useState("");
	const [slug, setSlug] = useState("");
	const [slugTouched, setSlugTouched] = useState(false);
	const [visibility, setVisibility] =
		useState<OrganizationVisibility>("private");
	const [confirmPublicVisibility, setConfirmPublicVisibility] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [isSaving, setIsSaving] = useState(false);
	const [isDeleting, setIsDeleting] = useState(false);
	const [confirmingDelete, setConfirmingDelete] = useState(false);

	// Hydrate local state once the org row loads. We avoid a render-keyed reset
	// so an in-progress edit isn't blown away by a background refetch.
	useEffect(() => {
		if (!targetOrg) return;
		setName(targetOrg.name);
		setSlug(targetOrg.slug);
		setVisibility(targetOrg.visibility);
		setSlugTouched(true);
	}, [targetOrg]);

	// Before the loading branch: a failed request also leaves `allOrgs`
	// undefined, so keying the skeleton on that alone left this page spinning
	// forever. A failed refetch that still has a cached list is not an error
	// state — keep rendering the settings.
	// Only a server failure, not any error: a 401 here means "sign in", and the
	// "not a member" card below already says the right thing for it.
	if (isServerError(orgsError) && allOrgs === undefined) {
		return (
			<Card role="alert">
				<CardHeader>
					<CardTitle>Couldn't load organizations</CardTitle>
				</CardHeader>
				<CardContent>
					<p className="text-sm text-muted-foreground">
						Please try again in a moment.
					</p>
				</CardContent>
			</Card>
		);
	}

	if (allOrgs === undefined) {
		return (
			<div className="max-w-2xl space-y-6">
				<TabLoadingState label="organization" variant="cards" cards={1} />
				<TabLoadingState label="visibility" variant="panel" />
			</div>
		);
	}

	if (!targetOrg) {
		return (
			<Card>
				<CardHeader>
					<CardTitle>Organization not found</CardTitle>
				</CardHeader>
				<CardContent>
					<p className="text-sm text-muted-foreground">
						You aren't a member of an organization at{" "}
						<span className="font-mono">{owner}</span>, or it has been deleted.
					</p>
				</CardContent>
			</Card>
		);
	}

	const goToOwner = (nextSlug: string) => {
		const target = buildOwnerHref(nextSlug);
		if (target.kind === "cross-host") {
			window.location.assign(target.href);
			return;
		}
		void navigate({ to: target.to as "/" });
	};

	const handleVisibilityChoice = (next: OrganizationVisibility) => {
		if (next === "public" && targetOrg.visibility !== "public") {
			setConfirmPublicVisibility(true);
			return;
		}
		setVisibility(next);
		setConfirmPublicVisibility(false);
	};

	const handleSave = async () => {
		const trimmedName = name.trim();
		if (!trimmedName) {
			setError("Name is required");
			return;
		}
		const trimmedSlug = slug.trim() || slugifyOrganizationName(trimmedName);
		if (!trimmedSlug) {
			setError("Slug is required");
			return;
		}

		setIsSaving(true);
		setError(null);

		try {
			const identityChanged =
				trimmedName !== targetOrg.name || trimmedSlug !== targetOrg.slug;
			const visibilityChanged = visibility !== targetOrg.visibility;
			let nextSlug = targetOrg.slug;

			if (identityChanged) {
				const result = await organization.update({
					organizationId: targetOrg.id,
					data: { name: trimmedName, slug: trimmedSlug },
				});
				if (result.error) {
					setError(result.error.message || "Failed to update organization");
					return;
				}
				nextSlug = result.data?.slug ?? trimmedSlug;
			}

			if (visibilityChanged) {
				const updated = await updateOrganizationVisibility(
					nextSlug,
					visibility,
				);
				nextSlug = updated.slug;
			}

			if (identityChanged || visibilityChanged) {
				await queryClient.invalidateQueries({ queryKey: ["organizations"] });
				toast.success("Organization updated");
			}

			const isCurrentOrg =
				activeOrg?.id === targetOrg.id || urlOrgSlug === targetOrg.slug;
			const slugChanged = nextSlug !== targetOrg.slug;

			if (isCurrentOrg && slugChanged) {
				const subdomainOwner = getSubdomainOwner();
				const zone = getSubdomainZone();
				if (subdomainOwner === targetOrg.slug && zone) {
					const strippedPath =
						stripOwnerPrefix(window.location.pathname, targetOrg.slug) || "/";
					const target = `${window.location.protocol}//${nextSlug}.${zone}${strippedPath}${window.location.search}${window.location.hash}`;
					window.location.assign(target);
					return;
				}
				const nextPath = getRenamedOrganizationPath(
					window.location.pathname,
					targetOrg.slug,
					nextSlug,
				);
				void navigate({
					to: `${nextPath}${window.location.search}${window.location.hash}` as "/",
				});
				return;
			}
		} catch (e) {
			setError(
				e instanceof Error ? e.message : "Failed to update organization",
			);
		} finally {
			setIsSaving(false);
		}
	};

	const handleDelete = async () => {
		setIsDeleting(true);
		setError(null);

		try {
			const result = await organization.delete({
				organizationId: targetOrg.id,
			});
			if (result.error) {
				setError(result.error.message || "Failed to delete organization");
				return;
			}

			await queryClient.invalidateQueries({ queryKey: ["organizations"] });
			toast.success("Organization deleted");

			const memberOrgs = (allOrgs ?? []).filter((o) => o.is_member);
			const fallbackOrg = memberOrgs.find((o) => o.id !== targetOrg.id) ?? null;
			const isCurrentOrg =
				activeOrg?.id === targetOrg.id || urlOrgSlug === targetOrg.slug;

			if (isCurrentOrg && fallbackOrg) {
				await organization.setActive({ organizationId: fallbackOrg.id });
				goToOwner(fallbackOrg.slug);
				return;
			}
			if (isCurrentOrg) {
				const subdomainOwner = getSubdomainOwner();
				const zone = getSubdomainZone();
				if (subdomainOwner === targetOrg.slug && zone) {
					window.location.assign(`${window.location.protocol}//app.${zone}/`);
					return;
				}
				void navigate({ to: "/" });
				return;
			}
			void navigate({ to: "/" });
		} catch (e) {
			setError(
				e instanceof Error ? e.message : "Failed to delete organization",
			);
		} finally {
			setIsDeleting(false);
			setConfirmingDelete(false);
		}
	};

	const busy = isSaving || isDeleting;

	return (
		// Wide enough for the agent write-defaults matrix (4 action columns).
		<div className="max-w-full space-y-6">
			<Card>
				<CardHeader>
					<CardTitle>Identity</CardTitle>
				</CardHeader>
				<CardContent className="space-y-4">
					<div className="space-y-1.5">
						<Label htmlFor="org-name">Name</Label>
						<Input
							id="org-name"
							value={name}
							onChange={(e) => {
								setName(e.target.value);
								if (!slugTouched) {
									setSlug(slugifyOrganizationName(e.target.value));
								}
							}}
							placeholder="e.g. My Team"
							disabled={busy}
						/>
					</div>
					<div className="space-y-1.5">
						<Label htmlFor="org-slug">Slug</Label>
						<Input
							id="org-slug"
							value={slug}
							onChange={(e) => {
								setSlugTouched(true);
								setSlug(e.target.value);
							}}
							placeholder="e.g. my-team"
							disabled={busy}
						/>
						<p className="text-xs text-muted-foreground">
							Changing the slug rewrites this workspace's URL. Existing links to{" "}
							<span className="font-mono">/{targetOrg.slug}</span> redirect for
							a grace period.
						</p>
					</div>
				</CardContent>
			</Card>

			<section className="space-y-3 px-6">
				<div>
					<h2 className="text-base font-semibold leading-none">
						Workspace visibility
					</h2>
					<p className="mt-1 text-sm text-muted-foreground">
						Choose who can browse this workspace and its public pages.
					</p>
				</div>
				<div className="grid gap-2 sm:grid-cols-2">
					<button
						type="button"
						onClick={() => handleVisibilityChoice("private")}
						disabled={busy}
						className={`flex items-start gap-3 rounded-lg border p-3 text-left transition-colors ${
							visibility === "private"
								? "border-primary bg-primary/5"
								: "border-border hover:bg-muted/40"
						}`}
					>
						<Lock className="mt-0.5 h-4 w-4 shrink-0" />
						<div>
							<div className="text-sm font-medium">Private</div>
							<p className="text-xs text-muted-foreground">
								Only members can access this workspace.
							</p>
						</div>
					</button>
					<button
						type="button"
						onClick={() => handleVisibilityChoice("public")}
						disabled={busy}
						className={`flex items-start gap-3 rounded-lg border p-3 text-left transition-colors ${
							visibility === "public"
								? "border-primary bg-primary/5"
								: "border-border hover:bg-muted/40"
						}`}
					>
						<Globe2 className="mt-0.5 h-4 w-4 shrink-0" />
						<div>
							<div className="text-sm font-medium">Public</div>
							<p className="text-xs text-muted-foreground">
								Anyone can browse public pages for this workspace.
							</p>
						</div>
					</button>
				</div>
				{confirmPublicVisibility && (
					<div className="rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm">
						<p className="text-foreground">
							Make this workspace public? Catalog-style content may become
							visible outside the membership.
						</p>
						<div className="mt-2 flex gap-2">
							<Button
								type="button"
								size="sm"
								onClick={() => {
									setVisibility("public");
									setConfirmPublicVisibility(false);
								}}
								disabled={busy}
							>
								Confirm public
							</Button>
							<Button
								type="button"
								size="sm"
								variant="ghost"
								onClick={() => setConfirmPublicVisibility(false)}
								disabled={busy}
							>
								Cancel
							</Button>
						</div>
					</div>
				)}
			</section>

			<section className="space-y-2">
				<div className="flex items-baseline gap-2 px-0.5">
					<h2 className="flex items-center gap-1.5 text-sm font-semibold">
						<ShieldCheck className="h-3.5 w-3.5" />
						Agent write defaults
					</h2>
					<span className="text-[11px] text-muted-foreground">
						saves as you click · agents can only tighten
					</span>
				</div>
				<AgentPermissionsMatrix owner={owner} variant="org-floor" />
			</section>

			{error && (
				<div className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">
					{error}
				</div>
			)}

			<div className="flex justify-end gap-2">
				<Button
					variant="outline"
					onClick={() => void navigate({ to: `/${owner}` as "/" })}
					disabled={busy}
				>
					Cancel
				</Button>
				<Button onClick={handleSave} disabled={busy}>
					{isSaving ? <Spinner size="lg" className="mr-1.5" /> : null}
					{isSaving ? "Saving..." : "Save changes"}
				</Button>
			</div>

			<div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4">
				<p className="text-sm font-medium">Delete this organization</p>
				<p className="mt-1 text-xs text-muted-foreground">
					Permanently removes the organization and all members' workspace
					access. This cannot be undone.
				</p>
				<div className="mt-3">
					{!confirmingDelete ? (
						<Button
							variant="outline"
							size="sm"
							className="text-destructive hover:text-destructive"
							onClick={() => setConfirmingDelete(true)}
							disabled={busy}
						>
							<Trash2 className="mr-1.5 h-3.5 w-3.5" />
							Delete organization
						</Button>
					) : (
						<div className="flex items-center gap-2">
							<Button
								variant="destructive"
								size="sm"
								onClick={handleDelete}
								disabled={busy}
							>
								{isDeleting ? <Spinner className="mr-1.5" /> : null}
								Confirm delete
							</Button>
							<Button
								variant="ghost"
								size="sm"
								onClick={() => setConfirmingDelete(false)}
								disabled={busy}
							>
								Cancel
							</Button>
						</div>
					)}
				</div>
			</div>
		</div>
	);
}

