/**
 * Grid template: scope col + N action cols + optional remove col.
 * Each action column must fit a full 3-option segment (Auto / Ask / Deny)
 * without bleeding into neighbors — that overflow is what made the matrix
 * look like fused controls. Parent uses overflow-x-auto so narrow viewports
 * scroll instead of stacking cells on top of each other.
 */
function gridStyle(actionCount: number, hasRemove: boolean) {
	// Fit Auto/Ask/Deny without neighbor bleed. Sized for the agent main pane
	// (~48rem content at laptop widths) so Default rows rarely need H-scroll.
	const colMinRem = 10.25;
	const scopeMinRem = 5.5;
	const removeRem = hasRemove ? 1.5 : 0;
	const chromeRem = 2;
	const actions = `repeat(${actionCount}, minmax(${colMinRem}rem, 1fr))`;
	return {
		gridTemplateColumns: hasRemove
			? `minmax(${scopeMinRem}rem, 8rem) ${actions} ${removeRem}rem`
			: `minmax(${scopeMinRem}rem, 8rem) ${actions}`,
		minWidth: `${scopeMinRem + actionCount * colMinRem + removeRem + chromeRem}rem`,
	};
}

