import { AgentPermissionsMatrix } from "@/components/agents/agent-permissions-matrix";
import { AgentSubpageShell } from "@/components/agents/agent-subpage-shell";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";

export function AgentPermissionsIndexRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	// Permission endpoints require an org settings admin. The workbench already
	// hides the Permissions tab from regular members; this guard covers direct
	// URLs so a member never lands on a 403 error state.
	const { orgContext } = useOrgContext();
	const { isAdmin, isLoading } = useMembers(orgContext.organizationId);
	return (
		<AgentSubpageShell
			owner={owner}
			agentId={agentId}
			backLabel="Permissions"
			backTo="/$owner/agents/$agentId/permissions"
		>
			{isAdmin ? (
				<div className="space-y-4">
					<p className="text-center text-sm text-muted-foreground">
						Control which data, agent settings, and connector actions this agent
						may use automatically, with approval, or not at all.
					</p>
					<div className="overflow-x-auto">
						<AgentPermissionsMatrix owner={owner} agentId={agentId} />
					</div>
				</div>
			) : isLoading ? null : (
				<p className="text-center text-sm text-muted-foreground">
					Only organization admins can view or change agent permissions.
				</p>
			)}
		</AgentSubpageShell>
	);
}

