export function resolveDefaultView(
	schema: ViewResolutionSchema | undefined,
	{ isDerived }: { isDerived: boolean },
): EntityViewMode {
	const explicit = schema?.["x-lobu"]?.defaultView;
	if (explicit === "table" || explicit === "board" || explicit === "gallery") {
		// A pinned board/gallery on a derived type is meaningless — fall through.
		if (!(isDerived && explicit !== "table")) return explicit;
	}

	if (isDerived) return "table";
	// The two resolvers read their own annotations off a properties bag; the
	// loose `unknown`-valued shape here is runtime-compatible with the concrete
	// per-view property interfaces they declare.
	const loose = schema as {
		properties?: Record<string, never>;
	};
	if (resolveWorkflowField(loose)) return "board";
	if (resolveGalleryFields(loose)?.hasImageField) return "gallery";
	return "table";
}

