import { AgentSkillsIndex } from "@/components/agents/agent-skills-index";
import { AgentSubpageShell } from "@/components/agents/agent-subpage-shell";
import { skillKeyToRepo } from "@/lib/skill-route-key";

function SkillsShell({
	owner,
	agentId,
	children,
	showBack,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
}) {
	return (
		<AgentSubpageShell
			owner={owner}
			agentId={agentId}
			showBack={showBack}
			backLabel="Skills"
			backTo="/$owner/agents/$agentId/skills"
		>
			{children}
		</AgentSubpageShell>
	);
}

export function AgentSkillsIndexRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	return (
		<SkillsShell owner={owner} agentId={agentId}>
			<AgentSkillsIndex owner={owner} agentId={agentId} />
		</SkillsShell>
	);
}

export function AgentSkillsCreateRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	const navigate = useNavigate();

	return (
		<SkillsShell owner={owner} agentId={agentId}>
			<AgentSkillsCreate
				owner={owner}
				agentId={agentId}
				onBack={() => {
					void navigate({
						to: "/$owner/agents/$agentId/skills",
						params: { owner, agentId },
					});
				}}
			/>
		</SkillsShell>
	);
}

export function AgentSkillDetailRoute({
	owner,
	agentId,
	skillKey,
}: {
	owner: string;
	agentId: string;
	skillKey: string;
}) {
	// The detail "page" is the skill list with the chosen row expanded in place —
	// deep-linkable, but it reads as the card opening inline.
	return (
		<SkillsShell owner={owner} agentId={agentId}>
			<AgentSkillsIndex
				owner={owner}
				agentId={agentId}
				expandedRepo={skillKeyToRepo(skillKey)}
			/>
		</SkillsShell>
	);
}

import {
	DndContext,
	type DragEndEvent,
	KeyboardSensor,
	PointerSensor,
	closestCenter,
	useSensor,
	useSensors,
} from "@dnd-kit/core";
import {
	SortableContext,
	sortableKeyboardCoordinates,
	useSortable,
	verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useNavigate } from "@tanstack/react-router";
import { ChevronRight, GripVertical, Plus, Sparkles } from "lucide-react";
import { type ReactNode, useEffect, useMemo } from "react";
import { useAgentSkillEditor } from "@/components/agents/agent-skill-context";
import { AgentSkillDetail } from "@/components/agents/agent-skill-detail";
import { CatalogBadges } from "@/components/agents/catalog-badges";
import { AgentListRowSkeleton } from "@/components/agents/agent-loading-shells";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { buildSkillIndexCards } from "@/lib/skill-index-cards";
import { skillRepoToKey } from "@/lib/skill-route-key";
import { cn } from "@/lib/utils";

const SKILLS_LEDE =
	"Skills teach the agent reusable ways of working — in chat or from Behaviors. Drag to set priority; skills higher in the list are preferred when the agent picks tools and capabilities.";

export function AgentSkillsIndex({
	owner,
	agentId,
	expandedRepo,
}: {
	owner: string;
	agentId: string;
	/** When set, that skill's row is expanded in place to show its config. */
	expandedRepo?: string;
}) {
	const navigate = useNavigate();
	const {
		skillRows,
		catalog,
		isLoading,
		isSaving,
		reorderSkills,
		setSkillEnabledAndSave,
		addSkillFromCatalog,
	} = useAgentSkillEditor();

	// Deep-link / refresh onto /skills/:key for a catalog skill that isn't
	// installed yet: seed it into the editor (unsaved) so its row appears and
	// expands — matching the old standalone detail page, which self-seeded.
	useEffect(() => {
		if (!expandedRepo) return;
		if (skillRows.some((row) => row.repo === expandedRepo)) return;
		if (catalog?.catalog.some((entry) => entry.repo === expandedRepo)) {
			addSkillFromCatalog(expandedRepo);
		}
	}, [expandedRepo, skillRows, catalog, addSkillFromCatalog]);

	const cards = useMemo(() => buildSkillIndexCards(skillRows), [skillRows]);
	const sortableIds = useMemo(() => cards.map((card) => card.repo), [cards]);

	const sensors = useSensors(
		useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const goToCreate = () => {
		void navigate({
			to: "/$owner/agents/$agentId/skills/create",
			params: { owner, agentId },
		});
	};

	const addSkillButton = (
		<Button
			type="button"
			variant="outline"
			size="sm"
			className="h-8 shrink-0 text-xs"
			onClick={goToCreate}
		>
			<Plus className="mr-1.5 h-3.5 w-3.5" />
			Add skill
		</Button>
	);

	const toggleDetail = (repo: string) => {
		// Click the open row again (or its chevron) to collapse back to the list.
		if (repo === expandedRepo) {
			void navigate({
				to: "/$owner/agents/$agentId/skills",
				params: { owner, agentId },
			});
			return;
		}
		void navigate({
			to: "/$owner/agents/$agentId/skills/$skillKey",
			params: { owner, agentId, skillKey: skillRepoToKey(repo) },
		});
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		if (!over || active.id === over.id) return;
		reorderSkills(String(active.id), String(over.id));
	};

	if (isLoading) {
		return (
			<div className="space-y-4">
				<p className="text-sm text-muted-foreground">{SKILLS_LEDE}</p>
				<AgentListRowSkeleton rows={2} />
			</div>
		);
	}

	// Empty: single CTA in the empty state (no lede-row Add — same rule as
	// InfraTabScaffold and the connectors list).
	if (cards.length === 0) {
		return (
			<div className="space-y-4">
				<p className="text-sm text-muted-foreground">{SKILLS_LEDE}</p>
				<TabEmptyState
					icon={Sparkles}
					title="No skills yet"
					description="Add a system skill from the catalog or create a custom skill for this agent."
					actionLabel="Add skill"
					onAction={goToCreate}
				/>
			</div>
		);
	}

	return (
		<div className="space-y-4">
			{/* Lede left + outline Add right — matches connector list surfaces. */}
			<div className="flex flex-wrap items-center justify-between gap-3">
				<p className="min-w-0 flex-1 text-sm text-muted-foreground">
					{SKILLS_LEDE}
				</p>
				{addSkillButton}
			</div>

			<DndContext
				sensors={sensors}
				collisionDetection={closestCenter}
				onDragEnd={handleDragEnd}
			>
				<SortableContext
					items={sortableIds}
					strategy={verticalListSortingStrategy}
				>
					<div className="overflow-hidden rounded-lg border">
						{cards.map((card, index) => {
							const expanded = card.repo === expandedRepo;
							return (
								<SortableSkillRow
									key={card.id}
									card={card}
									rank={index + 1}
									disabled={isSaving}
									expanded={expanded}
									isLast={index === cards.length - 1}
									onToggle={() => toggleDetail(card.repo)}
									onToggleEnabled={(next) =>
										void setSkillEnabledAndSave(card.repo, next)
									}
									toggleDisabled={isSaving}
								>
									{expanded ? (
										<AgentSkillDetail
											owner={owner}
											agentId={agentId}
											skillKey={skillRepoToKey(card.repo)}
										/>
									) : null}
								</SortableSkillRow>
							);
						})}
					</div>
				</SortableContext>
			</DndContext>
		</div>
	);
}

function SortableSkillRow({
	card,
	rank,
	disabled,
	expanded,
	isLast,
	onToggle,
	onToggleEnabled,
	toggleDisabled,
	children,
}: {
	card: ReturnType<typeof buildSkillIndexCards>[number];
	rank: number;
	disabled: boolean;
	expanded: boolean;
	isLast: boolean;
	onToggle: () => void;
	onToggleEnabled: (enabled: boolean) => void;
	toggleDisabled: boolean;
	children?: ReactNode;
}) {
	// Collapse-to-drag: an open row can't be reordered, so the expanded form's
	// controls don't fight the drag handle.
	const dragDisabled = disabled || expanded;
	const {
		attributes,
		listeners,
		setNodeRef,
		transform,
		transition,
		isDragging,
	} = useSortable({ id: card.repo, disabled: dragDisabled });

	const style = {
		transform: CSS.Transform.toString(transform),
		transition,
	};

	return (
		<div
			ref={setNodeRef}
			style={style}
			className={cn(
				"bg-background",
				!isLast || expanded ? "border-b" : "",
				isDragging && "z-10 bg-card opacity-80 shadow-sm",
			)}
		>
			<div className="flex items-stretch gap-1 pr-3">
				<button
					type="button"
					className="flex shrink-0 cursor-grab touch-none items-center px-2 text-muted-foreground hover:text-foreground active:cursor-grabbing disabled:cursor-not-allowed disabled:opacity-50"
					aria-label={`Reorder ${card.name}`}
					disabled={dragDisabled}
					{...attributes}
					{...listeners}
				>
					<GripVertical className="h-4 w-4" />
				</button>
				<button
					type="button"
					className={cn(
