/** Destinations under the Configure dropdown. Chat is the sidebar agent row
 *  itself — not listed here. */
type AgentConfigDest =
	| "behaviors"
	| "skills"
	| "guardrails"
	| "permissions"
	| "models"
	| "settings";

const CONFIG_MENU: {
	key: AgentConfigDest;
	label: string;
	icon: ComponentType<{ className?: string }>;
	/** Requires org settings admin (write-gate envelope). */
	adminOnly?: boolean;
}[] = [
	{ key: "behaviors", label: "Behaviors", icon: ListChecks },
	{ key: "skills", label: "Skills", icon: Sparkles },
	{ key: "guardrails", label: "Guardrails", icon: Shield },
	{ key: "permissions", label: "Permissions", icon: Lock, adminOnly: true },
	{ key: "models", label: "Models", icon: Cpu },
	{ key: "settings", label: "Settings", icon: SettingsIcon },
];

/** Menu rows visible for the current role. Exported for unit tests. */
export function filterConfigMenu(isAdmin: boolean) {
	return CONFIG_MENU.filter((item) => !item.adminOnly || isAdmin);
}

/** Active configure destination for the pathname, or null on chat/conversations. */
function activeConfigDest(
	base: string,
	pathname: string,
): AgentConfigDest | null {
	for (const { key } of CONFIG_MENU) {
		if (
			pathname === `${base}/${key}` ||
			pathname.startsWith(`${base}/${key}/`)
		) {
			return key;
		}
	}
	// Legacy /identity URLs still resolve; identity fields live on Settings.
	if (pathname === `${base}/identity` || pathname === `${base}/identity/`) {
		return "settings";
	}
	return null;
}

function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

