import { Link, useNavigate } from "@tanstack/react-router";
import { Pencil, Plus, Radio, Trash2 } from "lucide-react";
import { useMemo, useState } from "react";
import { AgentTabShell } from "@/components/agents/agent-subpage-shell";
import {
	KindBadge,
	OutputChips,
} from "@/components/agents/behaviors/behavior-badges";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { StatusBadge } from "@/components/ui/status-badge";
import { useAgentWatchersList, useDeleteWatcher } from "@/hooks/use-watchers";
import {
	type Behavior,
	type BehaviorFacets,
	DEFAULT_FACETS,
	filterBehaviors,
	type KindFacet,
	mergeBehaviors,
	type OutputFacet,
	type StateFacet,
} from "@/lib/behaviors/model";
import { cn, FILLED_BOX } from "@/lib/utils";

const KIND_FACETS: { value: KindFacet; label: string }[] = [
	{ value: "all", label: "All" },
	{ value: "event", label: "Event" },
	{ value: "schedule", label: "Schedule" },
	{ value: "manual", label: "Manual" },
];
const OUTPUT_FACETS: { value: OutputFacet; label: string }[] = [
	{ value: "any", label: "Any output" },
	{ value: "reply", label: "Reply" },
	{ value: "silent", label: "Save in Lobu" },
];
const STATE_FACETS: { value: StateFacet; label: string }[] = [
	{ value: "any", label: "Any state" },
	{ value: "active", label: "Active" },
	{ value: "failing", label: "Failing" },
];

function FacetGroup<T extends string>({
	options,
	value,
	onChange,
}: {
	options: { value: T; label: string }[];
	value: T;
	onChange: (value: T) => void;
}) {
	return (
		<div className="inline-flex rounded-md border bg-muted/30 p-0.5 text-sm">
			{options.map((option) => (
				<button
					key={option.value}
					type="button"
					aria-pressed={value === option.value}
					onClick={() => onChange(option.value)}
					className={cn(
						"rounded px-3 py-1 transition-colors",
						value === option.value
							? "bg-background text-foreground shadow-sm"
							: "text-muted-foreground hover:text-foreground",
					)}
				>
					{option.label}
				</button>
			))}
		</div>
	);
}

function RemoveControl({
	pending,
	onConfirm,
}: {
	pending: boolean;
	onConfirm: () => void;
}) {
	const [confirming, setConfirming] = useState(false);
	if (!confirming) {
		return (
			<Button
				type="button"
				variant="ghost"
				size="icon"
				className="text-muted-foreground hover:text-destructive"
				aria-label="Delete"
				onClick={() => setConfirming(true)}
			>
				<Trash2 className="h-4 w-4" />
			</Button>
		);
	}
	return (
		<div className="flex items-center gap-1">
			<Button
				type="button"
				variant="destructive"
				size="sm"
				disabled={pending}
				onClick={onConfirm}
			>
				Delete
			</Button>
			<Button
				type="button"
				variant="ghost"
				size="sm"
				onClick={() => setConfirming(false)}
			>
				Cancel
			</Button>
		</div>
	);
}

