export function BehaviorsIndex({
	owner,
	agentId,
	agentName,
}: {
	owner: string;
	agentId: string;
	agentName: string;
}) {
	const navigate = useNavigate();
	const [facets, setFacets] = useState<BehaviorFacets>(DEFAULT_FACETS);
	const watchers = useAgentWatchersList(agentId);
	const deleteBehavior = useDeleteWatcher();
	const behaviors = useMemo(
		() => mergeBehaviors(watchers.data ?? []),
		[watchers.data],
	);
	const visible = useMemo(
		() => filterBehaviors(behaviors, facets),
		[behaviors, facets],
	);

	if (!watchers.isLoading && behaviors.length === 0) {
		return (
			<AgentTabShell>
				<TabEmptyState
					icon={Radio}
					title="No behaviors yet"
					description="Behaviors define when and where the agent acts autonomously. Add one triggered by an event, schedule, or explicit call."
					actionLabel="New behavior"
					onAction={() =>
						void navigate({
							to: "/$owner/agents/$agentId/behaviors/new",
							params: { owner, agentId },
							search: {},
						})
					}
				/>
			</AgentTabShell>
		);
	}

	return (
		<AgentTabShell>
			<div className="mb-4 flex items-start justify-between gap-4">
				<div>
					<h2 className="text-xl font-semibold">Behaviors</h2>
					<p className="mt-1 max-w-xl text-sm text-muted-foreground">
						Behaviors define when and where the agent acts autonomously — across
						connector events, schedules, and explicit calls.
					</p>
				</div>
				<Button asChild className="shrink-0">
					<Link
						to="/$owner/agents/$agentId/behaviors/new"
						params={{ owner, agentId }}
						search={{}}
					>
						<Plus className="mr-1.5 h-4 w-4" />
						New behavior
					</Link>
				</Button>
			</div>

			<div className="mb-4 flex flex-wrap items-center gap-2">
				<FacetGroup
					options={KIND_FACETS}
					value={facets.kind}
					onChange={(kind) => setFacets((current) => ({ ...current, kind }))}
				/>
				<FacetGroup
					options={OUTPUT_FACETS}
					value={facets.output}
					onChange={(output) =>
						setFacets((current) => ({ ...current, output }))
					}
				/>
				<FacetGroup
					options={STATE_FACETS}
					value={facets.state}
					onChange={(state) => setFacets((current) => ({ ...current, state }))}
				/>
			</div>

			{watchers.isLoading ? (
				<div className="flex flex-col gap-2">
					{[0, 1, 2].map((index) => (
						<Skeleton key={index} className="h-16 w-full rounded-lg" />
					))}
				</div>
			) : visible.length === 0 ? (
				<TabEmptyState
					icon={Radio}
					title="No behaviors match these filters"
					description="Adjust the trigger, output, or state filters to see more."
				/>
			) : (
				<div className="flex flex-col gap-2">
					{visible.map((behavior) => (
						<BehaviorRow
							key={behavior.key}
							behavior={behavior}
							agentName={agentName}
							owner={owner}
							agentId={agentId}
							removing={deleteBehavior.isPending}
							onRemove={() =>
								deleteBehavior.mutate(behavior.watcher.behavior_id)
							}
						/>
					))}
				</div>
			)}
		</AgentTabShell>
	);
}

