import { useNavigate } from "@tanstack/react-router";
import { Plus } from "lucide-react";
import { useMemo, useState } from "react";
import { AgentCreatePageHeader } from "@/components/agents/agent-subpage-shell";
import { useAgentSkillEditor } from "@/components/agents/agent-skill-context";
import {
	CatalogPicker,
	CatalogPickerSkeleton,
} from "@/components/agents/catalog-picker";
import { Button } from "@/components/ui/button";
import { FormFooter } from "@/components/ui/form-footer";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
	buildSkillCatalogItems,
	filterSkillCatalog,
} from "@/lib/skill-catalog";
import { skillRepoToKey } from "@/lib/skill-route-key";
import { FILLED_BOX, cn } from "@/lib/utils";

export function AgentSkillsCreate({
	owner,
	agentId,
	onBack,
	backLabel = "Skills",
}: {
	owner: string;
	agentId: string;
	onBack?: () => void;
	backLabel?: string;
}) {
	const navigate = useNavigate();
	const [searchQuery, setSearchQuery] = useState("");
	const [showCustomForm, setShowCustomForm] = useState(false);
	const [customName, setCustomName] = useState("");
	const [customInstructions, setCustomInstructions] = useState("");

	const { skillRows, catalog, isLoading, addSkillFromCatalog, addCustomSkill } =
		useAgentSkillEditor();

	const installedRepos = useMemo(
		() => new Set(skillRows.map((row) => row.repo)),
		[skillRows],
	);

	const catalogItems = useMemo(
		() => buildSkillCatalogItems(catalog?.catalog ?? [], installedRepos),
		[catalog?.catalog, installedRepos],
	);

	const filtered = useMemo(
		() => filterSkillCatalog(catalogItems, searchQuery),
		[catalogItems, searchQuery],
	);

	const goToDetail = (repo: string) => {
		addSkillFromCatalog(repo);
		void navigate({
			to: "/$owner/agents/$agentId/skills/$skillKey",
			params: { owner, agentId, skillKey: skillRepoToKey(repo) },
		});
	};

	const handleAddCustom = () => {
		const repo = addCustomSkill({
			name: customName,
			instructions: customInstructions,
		});
		if (!repo) return;
		void navigate({
			to: "/$owner/agents/$agentId/skills/$skillKey",
			params: { owner, agentId, skillKey: skillRepoToKey(repo) },
		});
	};

	const pageHeader = onBack ? (
		<AgentCreatePageHeader
			title="Add a skill"
			description="Skills teach the agent reusable ways of working — in chat or from Behaviors. Pick one from the catalog or create a custom skill for this agent."
			onBack={onBack}
			backLabel={backLabel}
		/>
	) : (
		<div className="space-y-1">
			<h1 className="text-xl font-semibold">Add a skill</h1>
			<p className="text-sm text-muted-foreground">
				Skills teach the agent reusable ways of working — in chat or from
				Behaviors. Pick one from the catalog or create a custom skill for this
				agent.
			</p>
		</div>
	);

	return (
		<div className="space-y-6">
			{pageHeader}

			<div className={cn(FILLED_BOX, "w-full")}>
				{!showCustomForm ? (
					<button
						type="button"
						className="flex w-full items-center gap-3 p-3 text-left text-muted-foreground transition-colors hover:text-foreground"
						onClick={() => setShowCustomForm(true)}
					>
						<div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted">
							<Plus className="h-4 w-4" />
						</div>
						<div>
							<p className="text-sm font-medium">Create custom skill</p>
							<p className="text-xs text-muted-foreground">
								Define instructions and packages
							</p>
						</div>
					</button>
				) : (
					<div className="space-y-3 p-3">
						<div className="grid gap-3">
							<div className="grid gap-2">
								<Label htmlFor="custom-skill-name">Name</Label>
								<Input
									id="custom-skill-name"
									value={customName}
									onChange={(e) => setCustomName(e.target.value)}
									placeholder="my-skill"
								/>
							</div>
							<div className="grid gap-2">
								<Label htmlFor="custom-skill-instructions">Instructions</Label>
								<Textarea
									id="custom-skill-instructions"
									value={customInstructions}
									onChange={(e) => setCustomInstructions(e.target.value)}
									placeholder="Instructions for the agent when this skill is active..."
									rows={3}
								/>
							</div>
						</div>
						<FormFooter onCancel={() => setShowCustomForm(false)}>
							<Button
								type="button"
								size="sm"
								onClick={handleAddCustom}
								disabled={!customName.trim()}
							>
								Add custom skill
							</Button>
						</FormFooter>
					</div>
				)}
			</div>

			{isLoading ? (
				<CatalogPickerSkeleton />
			) : (
				<CatalogPicker
					items={filtered}
					searchQuery={searchQuery}
					onSearchChange={setSearchQuery}
					onSelect={(item) => goToDetail(item.key)}
					searchPlaceholder="Search skills..."
					searchAriaLabel="Search skills"
					emptyMessage={
						searchQuery.trim()
							? `No skills match "${searchQuery}"`
							: catalogItems.length === 0
								? "All catalog skills are already configured"
								: "No skills available"
					}
				/>
			)}
		</div>
	);
}

import { ChevronRight, Search } from "lucide-react";
import type { ReactNode } from "react";
import { CatalogBadges } from "@/components/agents/catalog-badges";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";

export interface CatalogPickerItem {
	key: string;
	name: string;
	description: string;
	badges: string[];
}

/** Four-column catalog card grid. */
export function CatalogCardGridSkeleton({
	count = 4,
}: {
	count?: number;
}) {
	return (
		<div
			className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-4"
			role="status"
			aria-label="Loading catalog"
		>
			{Array.from({ length: count }).map((_, i) => (
				<Skeleton
					// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton cards
					key={i}
					className="min-h-[5.5rem] w-full rounded-lg"
				/>
			))}
		</div>
	);
}

export function ConnectorCatalogListSkeleton({
	count = 8,
}: {
	count?: number;
}) {
	return (
		<div
			className="overflow-hidden rounded-lg border"
			role="status"
			aria-label="Loading connector catalog"
		>
			{Array.from({ length: count }).map((_, i) => (
				<div
					// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
					key={i}
					// bg-card matches the loaded rows' surface, so resolving the
					// list swaps content without repainting the background.
					className={`flex items-center gap-3 bg-card px-3 py-2.5 ${
						i === count - 1 ? "" : "border-b"
					}`}
				>
					<Skeleton className="h-8 w-8 shrink-0 rounded-lg" />
					<div className="min-w-0 flex-1 space-y-1.5">
						<Skeleton className="h-3.5 w-24 rounded" />
						<Skeleton className="h-3 w-48 max-w-full rounded" />
					</div>
					<Skeleton className="h-4 w-14 shrink-0 rounded-full" />
					<Skeleton className="h-4 w-4 shrink-0 rounded" />
				</div>
			))}
		</div>
	);
}

/** Catalog search + card grid while template/provider/skill catalogs load. */
export function CatalogPickerSkeleton({
	count = 4,
	withSearch = true,
}: {
	count?: number;
	withSearch?: boolean;
}) {
	return (
		<div className="space-y-3" role="status" aria-label="Loading catalog">
			{withSearch ? <Skeleton className="h-9 w-full rounded-md" /> : null}
			<CatalogCardGridSkeleton count={count} />
		</div>
	);
}

export function CatalogPicker({
	items,
	searchQuery,
	onSearchChange,
	onSelect,
	emptyMessage,
	searchPlaceholder = "Search...",
	searchAriaLabel = "Search catalog",
	renderTitle,
}: {
	items: CatalogPickerItem[];
	searchQuery: string;
	onSearchChange: (value: string) => void;
	onSelect: (item: CatalogPickerItem) => void;
	emptyMessage?: string;
	searchPlaceholder?: string;
	searchAriaLabel?: string;
	renderTitle?: (item: CatalogPickerItem) => ReactNode;
}) {
	return (
		<div className="space-y-3">
			<div className="relative">
				<Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
				<Input
					aria-label={searchAriaLabel}
					placeholder={searchPlaceholder}
					value={searchQuery}
					onChange={(e) => onSearchChange(e.target.value)}
					className="pl-9"
				/>
			</div>
			{items.length === 0 ? (
				<p className="py-4 text-center text-sm text-muted-foreground">
					{emptyMessage ?? `No items match "${searchQuery}"`}
				</p>
			) : (
				<div className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-4">
					{items.map((item) => (
						<button
							key={item.key}
							type="button"
							className="flex h-full flex-col gap-2 rounded-lg bg-card p-3 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground"
							onClick={() => onSelect(item)}
						>
							<div className="flex items-start gap-2">
								<div className="min-w-0 flex-1">
									{renderTitle ? (
										renderTitle(item)
									) : (
										<span className="text-sm font-medium">{item.name}</span>
									)}
								</div>
								<ChevronRight className="mt-1 h-4 w-4 shrink-0 text-muted-foreground" />
							</div>
							<p className="line-clamp-2 text-xs text-muted-foreground">
								{item.description}
							</p>
							<CatalogBadges badges={item.badges} />
						</button>
					))}
				</div>
			)}
		</div>
	);
}

