export function BehaviorDraftEditor({
	agentId,
	onCancel,
	initialTriggers,
}: {
	agentId: string;
	onCancel: () => void;
	/** Prefill one or more activation contracts (e.g. chat-link deep link). */
	initialTriggers?: Array<Record<string, unknown>>;
}) {
	const { org } = useCurrentOrg();
	const [triggersDraft, setTriggersDraft] = useState<BehaviorTriggersDraft>({
		ready: false,
		triggers: [],
	});
	const handleTriggersChange = useCallback((draft: BehaviorTriggersDraft) => {
		setTriggersDraft((prev) =>
			JSON.stringify(prev) === JSON.stringify(draft) ? prev : draft,
		);
	}, []);

	return (
		<CreateWatcherForm
			organizationId={org?.id ?? ""}
			prefillAgentId={agentId}
			initialMode="scratch"
			onClose={onCancel}
			onSuccess={onCancel}
			hideHeader
			submitLabel="Create Behavior"
			submitDisabled={!triggersDraft.ready}
			createFields={{
				triggers: triggersDraft.triggers,
			}}
			triggerFields={
				<BehaviorTriggersEditor
					key={JSON.stringify(initialTriggers ?? "new")}
					organizationId={org?.id ?? null}
					initialTriggers={initialTriggers}
					onChange={handleTriggersChange}
				/>
			}
		/>
	);
}

