import { useNavigate } from "@tanstack/react-router";
import { ArrowLeft } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/**
 * One centered column width for every agent sub-tab (index + create/detail), so
 * no tab reads wider than its neighbors. Wrap each tab's content in this instead
 * of hand-writing `mx-auto w-full max-w-3xl` per page. Pass `className` to widen
 * (e.g. permissions matrix uses max-w-6xl).
 */
export function AgentTabShell({
	children,
	className,
}: {
	children: ReactNode;
	className?: string;
}) {
	return (
		<div className={cn("mx-auto w-full max-w-3xl pb-6", className)}>
			{children}
		</div>
	);
}

