import { useNavigate } from '@tanstack/react-router';
import { toast } from 'sonner';
import { AgentGuardrailForm } from '@/components/agents/agent-guardrail-form';
import { FormLoadingShell } from '@/components/ui/form-loading-shell';
import {
  useAgentConfig,
  useGuardrailJudgeDefault,
  useGuardrailsCatalog,
  useUpdateAgentConfig,
} from '@/lib/api';
import {
  addCustomGuardrail,
  type CustomGuardrailDraft,
  validateCustomGuardrail,
} from '@/lib/custom-guardrail-edits';

export function AgentGuardrailsCreate({
  owner,
  agentId,
}: {
  owner: string;
  agentId: string;
}) {
  const navigate = useNavigate();
  const { data: agentConfig, isLoading: isConfigLoading } =
    useAgentConfig(agentId);
  const { data: catalog, isLoading: isCatalogLoading } =
    useGuardrailsCatalog(agentId);
  const { data: judgeModelDefault = null, isLoading: isJudgeLoading } =
    useGuardrailJudgeDefault(agentId);
  const isLoading = isConfigLoading || isCatalogLoading || isJudgeLoading;
  const updateAgentConfig = useUpdateAgentConfig(agentId);

  const existing = agentConfig?.guardrailsInline ?? [];
  const builtinNames = (catalog ?? []).map((c) => c.name);

  const handleSubmit = async (draft: CustomGuardrailDraft) => {
    if (!agentConfig) {
      toast.error('Still loading agent settings — try again in a moment');
      return;
    }
    const error = validateCustomGuardrail(
      draft,
      existing,
      builtinNames,
      judgeModelDefault
    );
    if (error) {
      toast.error(error);
      return;
    }
    try {
      await updateAgentConfig.mutateAsync({
        guardrailsInline: addCustomGuardrail(existing, draft),
      });
      toast.success('Guardrail created');
      void navigate({
        to: '/$owner/agents/$agentId/guardrails',
        params: { owner, agentId },
      });
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : 'Failed to create guardrail'
      );
    }
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1 text-center">
        <h2 className="text-lg font-semibold">New custom guardrail</h2>
        <p className="text-sm text-muted-foreground">
          A custom guardrail judges text at one stage against a policy you write.
        </p>
      </div>
      {isLoading ? (
        <FormLoadingShell rows={4} />
      ) : (
        <AgentGuardrailForm
          judgeModelDefault={judgeModelDefault}
          submitLabel="Create guardrail"
          submitting={updateAgentConfig.isPending}
          onSubmit={handleSubmit}
          onCancel={() =>
            void navigate({
              to: '/$owner/agents/$agentId/guardrails',
              params: { owner, agentId },
            })
          }
        />
      )}
    </div>
  );
}

